import{_ as e,C as t,c as i,o,j as a,b as r,a0 as n,a as l,w as s,G as u,a1 as h}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Building Your Pre-Shot Routine","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/mental-strength/pre-shot-routine.md","filePath":"en/education/mental-strength/pre-shot-routine.md"}');const d=e({name:"en/education/mental-strength/pre-shot-routine.md"},[["render",function(e,c,d,p,m,g){const f=t("Mermaid");return o(),i("div",null,[c[1]||(c[1]=a("h1",{id:"building-your-pre-shot-routine",tabindex:"-1"},[l("Building Your Pre-Shot Routine "),a("a",{class:"header-anchor",href:"#building-your-pre-shot-routine","aria-label":'Permalink to "Building Your Pre-Shot Routine"'},"​")],-1)),c[2]||(c[2]=a("p",null,"Your pre-shot routine is one of the most powerful tools in your mental game. It's a consistent sequence of actions that prepares you for each throw and triggers your best performance state.",-1)),c[3]||(c[3]=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"The Big Idea"),a("p",null,[a("strong",null,"Your routine is your gateway to the zone."),l(' A consistent pre-shot routine signals your brain: "It\'s time to execute." With repetition, it becomes an automatic trigger for peak performance.')])],-1)),(o(),r(h,null,{default:s(()=>[u(f,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BStart%20Routine%5D%20--%3E%20B%5BBrain%20Recognizes%20Pattern%5D%0A%20%20%20%20B%20--%3E%20C%5BAutomatic%20State%20Shift%5D%0A%20%20%20%20C%20--%3E%20D%5BExecution%20Mode%5D%0A%20%20%20%20D%20--%3E%20E%5BPeak%20Performance%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=n('<h2 id="why-routines-work" tabindex="-1">Why Routines Work <a class="header-anchor" href="#why-routines-work" aria-label="Permalink to &quot;Why Routines Work&quot;">​</a></h2><h3 id="consistency-creates-confidence" tabindex="-1">Consistency Creates Confidence <a class="header-anchor" href="#consistency-creates-confidence" aria-label="Permalink to &quot;Consistency Creates Confidence&quot;">​</a></h3><p>When you do the same thing every time, you remove variables. Your body knows what&#39;s coming. This creates a sense of control and familiarity, even in unfamiliar situations.</p><h3 id="routines-trigger-states" tabindex="-1">Routines Trigger States <a class="header-anchor" href="#routines-trigger-states" aria-label="Permalink to &quot;Routines Trigger States&quot;">​</a></h3><p>With repetition, your routine becomes linked to your performance state. Starting the routine automatically begins the mental shift to execution mode.</p><h3 id="routines-block-distractions" tabindex="-1">Routines Block Distractions <a class="header-anchor" href="#routines-block-distractions" aria-label="Permalink to &quot;Routines Block Distractions&quot;">​</a></h3><p>A routine gives your mind something to focus on. There&#39;s no room for worry about the score, the audience, or what might happen.</p><h3 id="routines-manage-arousal" tabindex="-1">Routines Manage Arousal <a class="header-anchor" href="#routines-manage-arousal" aria-label="Permalink to &quot;Routines Manage Arousal&quot;">​</a></h3><p>A well-designed routine helps regulate your energy level - calming you if you&#39;re too amped, focusing you if you&#39;re flat.</p><h2 id="elements-of-an-effective-routine" tabindex="-1">Elements of an Effective Routine <a class="header-anchor" href="#elements-of-an-effective-routine" aria-label="Permalink to &quot;Elements of an Effective Routine&quot;">​</a></h2><h3 id="phase-1-assessment-outside-the-circle" tabindex="-1">Phase 1: Assessment (Outside the Circle) <a class="header-anchor" href="#phase-1-assessment-outside-the-circle" aria-label="Permalink to &quot;Phase 1: Assessment (Outside the Circle)&quot;">​</a></h3><p>Before you step in, gather information:</p><ul><li>Read the terrain (slopes, obstacles, surface)</li><li>Assess the situation (score, boule positions)</li><li>Choose your target and landing spot</li><li>Decide on throw type (point, shoot, lob, roll)</li></ul><p><strong>This is where thinking happens.</strong> Take your time here.</p><h3 id="phase-2-transition-entering-the-circle" tabindex="-1">Phase 2: Transition (Entering the Circle) <a class="header-anchor" href="#phase-2-transition-entering-the-circle" aria-label="Permalink to &quot;Phase 2: Transition (Entering the Circle)&quot;">​</a></h3><p>The shift from thinking to doing:</p><ul><li>Physical action (step into circle in a consistent way)</li><li>Mental cue (a word or phrase that signals &quot;execution mode&quot;)</li><li>Breath (one conscious breath to center yourself)</li></ul><p><strong>This is the switch.</strong> Analysis stops here.</p><h3 id="phase-3-setup-in-the-circle" tabindex="-1">Phase 3: Setup (In the Circle) <a class="header-anchor" href="#phase-3-setup-in-the-circle" aria-label="Permalink to &quot;Phase 3: Setup (In the Circle)&quot;">​</a></h3><p>Prepare your body:</p><ul><li>Consistent stance (same every time)</li><li>Grip check (feel the boule)</li><li>Alignment to target</li><li>Physical trigger (a small movement that&#39;s yours)</li></ul><h3 id="phase-4-visualization-brief" tabindex="-1">Phase 4: Visualization (Brief) <a class="header-anchor" href="#phase-4-visualization-brief" aria-label="Permalink to &quot;Phase 4: Visualization (Brief)&quot;">​</a></h3><p>See the throw before you make it:</p><ul><li>Picture the ball&#39;s path (2-3 seconds maximum)</li><li>Feel the successful throw</li><li>Connect visually with your target</li></ul><h3 id="phase-5-execution" tabindex="-1">Phase 5: Execution <a class="header-anchor" href="#phase-5-execution" aria-label="Permalink to &quot;Phase 5: Execution&quot;">​</a></h3><p>Make the throw:</p><ul><li>External focus (target only)</li><li>Trust your body</li><li>Release without hesitation</li><li>Follow through naturally</li></ul><h2 id="building-your-personal-routine" tabindex="-1">Building Your Personal Routine <a class="header-anchor" href="#building-your-personal-routine" aria-label="Permalink to &quot;Building Your Personal Routine&quot;">​</a></h2><h3 id="step-1-observe-what-you-already-do" tabindex="-1">Step 1: Observe What You Already Do <a class="header-anchor" href="#step-1-observe-what-you-already-do" aria-label="Permalink to &quot;Step 1: Observe What You Already Do&quot;">​</a></h3><p>You probably have some routine already. Notice:</p><ul><li>What do you do before good throws?</li><li>What feels natural to you?</li><li>What helps you focus?</li></ul><h3 id="step-2-design-your-routine" tabindex="-1">Step 2: Design Your Routine <a class="header-anchor" href="#step-2-design-your-routine" aria-label="Permalink to &quot;Step 2: Design Your Routine&quot;">​</a></h3><p>Create a sequence that includes:</p><ul><li>[ ] Assessment phase</li><li>[ ] Clear transition moment</li><li>[ ] Consistent physical setup</li><li>[ ] Brief visualization</li><li>[ ] Execution trigger</li></ul><h3 id="step-3-write-it-down" tabindex="-1">Step 3: Write It Down <a class="header-anchor" href="#step-3-write-it-down" aria-label="Permalink to &quot;Step 3: Write It Down&quot;">​</a></h3><p>Be specific. Example:</p><ol><li><strong>Assess:</strong> Read terrain, choose landing spot</li><li><strong>Transition:</strong> Step into circle with left foot first, say &quot;trust&quot;</li><li><strong>Setup:</strong> Feet shoulder-width, grip check, align shoulders</li><li><strong>Visualize:</strong> See the path, feel the release</li><li><strong>Execute:</strong> Eyes on target, throw</li></ol><h3 id="step-4-practice-religiously" tabindex="-1">Step 4: Practice Religiously <a class="header-anchor" href="#step-4-practice-religiously" aria-label="Permalink to &quot;Step 4: Practice Religiously&quot;">​</a></h3><p>Use your routine on EVERY throw in practice:</p><ul><li>Easy throws</li><li>Difficult throws</li><li>When you&#39;re tired</li><li>When you&#39;re fresh</li></ul><p>The routine must become automatic.</p><h3 id="step-5-refine-over-time" tabindex="-1">Step 5: Refine Over Time <a class="header-anchor" href="#step-5-refine-over-time" aria-label="Permalink to &quot;Step 5: Refine Over Time&quot;">​</a></h3><p>Your routine will evolve. Notice what works and adjust. But don&#39;t change it during competition - only between events.</p><h2 id="routine-timing" tabindex="-1">Routine Timing <a class="header-anchor" href="#routine-timing" aria-label="Permalink to &quot;Routine Timing&quot;">​</a></h2><p>Your routine should take a consistent amount of time:</p><ul><li>Too fast: You&#39;re rushing, not properly prepared</li><li>Too slow: You&#39;re overthinking, losing flow</li><li>Just right: Enough time to prepare, not so much that you think too much</li></ul><p><strong>Typical timing:</strong></p><ul><li>Assessment: 5-10 seconds</li><li>Transition + Setup: 3-5 seconds</li><li>Visualization + Execution: 3-5 seconds</li><li><strong>Total: 10-20 seconds</strong></li></ul><h2 id="common-routine-mistakes" tabindex="-1">Common Routine Mistakes <a class="header-anchor" href="#common-routine-mistakes" aria-label="Permalink to &quot;Common Routine Mistakes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mistake</th><th>Problem</th><th>Solution</th></tr></thead><tbody><tr><td>Skipping in practice</td><td>Routine isn&#39;t automatic</td><td>Use it every single throw</td></tr><tr><td>Too complicated</td><td>Hard to remember under pressure</td><td>Simplify to essentials</td></tr><tr><td>Thinking during execution</td><td>Disrupts automatic performance</td><td>Clear transition point</td></tr><tr><td>Inconsistent timing</td><td>Creates uncertainty</td><td>Practice with consistent pace</td></tr><tr><td>Changing mid-competition</td><td>Introduces doubt</td><td>Stick with what you know</td></tr></tbody></table><h2 id="routine-troubleshooting" tabindex="-1">Routine Troubleshooting <a class="header-anchor" href="#routine-troubleshooting" aria-label="Permalink to &quot;Routine Troubleshooting&quot;">​</a></h2><p><strong>If you&#39;re rushing:</strong></p><ul><li>Add a breath at the transition</li><li>Slow your setup movements</li><li>Pause before visualization</li></ul><p><strong>If you&#39;re overthinking:</strong></p><ul><li>Shorten the routine</li><li>Use a stronger transition cue</li><li>Focus more externally</li></ul><p><strong>If you&#39;re inconsistent:</strong></p><ul><li>Video yourself to check</li><li>Practice the routine without throwing</li><li>Get feedback from a partner</li></ul><h2 id="sample-routines" tabindex="-1">Sample Routines <a class="header-anchor" href="#sample-routines" aria-label="Permalink to &quot;Sample Routines&quot;">​</a></h2><h3 id="simple-routine" tabindex="-1">Simple Routine <a class="header-anchor" href="#simple-routine" aria-label="Permalink to &quot;Simple Routine&quot;">​</a></h3><ol><li>Choose target</li><li>Step in, breathe</li><li>Grip, align</li><li>See it, throw it</li></ol><h3 id="detailed-routine" tabindex="-1">Detailed Routine <a class="header-anchor" href="#detailed-routine" aria-label="Permalink to &quot;Detailed Routine&quot;">​</a></h3><ol><li>Read terrain, pick landing spot</li><li>Step in left foot first</li><li>Say &quot;smooth&quot; internally</li><li>One breath, shoulders drop</li><li>Feet set, grip check</li><li>Align shoulders to target</li><li>See the path (2 seconds)</li><li>Eyes lock on target</li><li>Throw</li></ol><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>Your routine is your anchor. In chaos, it&#39;s your constant.</p></blockquote><p>Build it carefully. Practice it always. Trust it completely.</p>',65))])}]]);export{c as __pageData,d as default};
